import { useState } from "react";
function ShoppingItem({ item }) {
  const [text, setText] = useState("Apple");

  return (
    <li>
      {item.text}
      <button className="remove-item btn-link text-red">
        <i className="fa-solid fa-xmark"></i>
      </button>
    </li>
  );
}

export default ShoppingItem;
